// Package websub subscribes the configured YouTube channel feed to Google's
// WebSub hub and turns verified upload notifications into a queued YouTube
// sync. A notification never writes snapshots itself: it only wakes the same
// bounded source and media steps that timers and operators run, so the RSS
// and stream-page reads remain the single source of stored data.
//
// The operator enables the subscription and sets the public callback URL in
// /admin; the HMAC secret is generated by the server (see Admin).
package websub

import (
	"bytes"
	"context"
	"crypto/hmac"
	"crypto/sha1"
	"crypto/sha256"
	"crypto/sha512"
	"encoding/hex"
	"encoding/xml"
	"errors"
	"fmt"
	"hash"
	"io"
	"net/http"
	"net/url"
	"os"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"
)

const (
	// HubURL is Google's public WebSub hub that serves YouTube feeds.
	HubURL = "https://pubsubhubbub.appspot.com/subscribe"
	// CallbackPath is the route the public callback URL must reach.
	CallbackPath = "/api/websub/youtube"
	topicBase    = "https://www.youtube.com/xml/feeds/videos.xml?channel_id="

	MaxNotificationBytes = 256 * 1024
	maxHubResponseBytes  = 64 * 1024
	maxChallengeBytes    = 1024
	maxCallbackLength    = 2048
	minSecretLength      = 16
	maxSecretLength      = 199

	// LeaseSeconds is requested on every subscription; renewal happens at
	// half the lease the hub grants.
	LeaseSeconds = 5 * 24 * 60 * 60
	// minRenewal bounds how often a verification (which anyone can send for
	// the public topic) can make this process contact the hub again.
	minRenewal     = time.Hour
	subscribeRetry = 15 * time.Minute
	// verifyWindow is how long after a hub request its verification may
	// change state.
	verifyWindow = time.Hour
	// unsubscribeAttempts bounds retries for a retired callback; its lease
	// expires on its own anyway.
	unsubscribeAttempts = 3

	// debounce coalesces bursts (upload plus metadata edits) and gives the
	// public RSS feed time to list the new entry before the sync reads it.
	debounce = time.Minute
	// minTriggerGap bounds how often notifications can start a sync.
	minTriggerGap = 2 * time.Minute
	triggerRetry  = 30 * time.Second
	tickInterval  = 5 * time.Second
)

var (
	channelPattern = regexp.MustCompile(`^UC[A-Za-z0-9_-]{22}$`)
	videoPattern   = regexp.MustCompile(`^[A-Za-z0-9_-]{11}$`)
)

// Options is one subscription. Secret signs hub notifications and is never
// written to logs or responses.
type Options struct {
	CallbackURL string
	Secret      string
	ChannelID   string
}

// ErrConfig reports an incomplete or unsafe configuration without echoing it.
var ErrConfig = errors.New("invalid YouTube WebSub configuration")

// ValidCallback requires an absolute HTTPS URL without credentials or a
// fragment.
func ValidCallback(callback string) bool {
	u, err := url.Parse(callback)
	return err == nil && len(callback) <= maxCallbackLength && u.Scheme == "https" && u.Host != "" &&
		u.User == nil && u.Fragment == "" && u.Opaque == ""
}

// Validate requires a valid callback, a bounded secret and a well-formed
// channel ID.
func (o Options) Validate() error {
	if !ValidCallback(o.CallbackURL) {
		return ErrConfig
	}
	if n := len(o.Secret); n < minSecretLength || n > maxSecretLength || strings.TrimSpace(o.Secret) != o.Secret {
		return ErrConfig
	}
	if !channelPattern.MatchString(o.ChannelID) {
		return ErrConfig
	}
	return nil
}

// Topic is the channel feed URL the hub publishes.
func Topic(channelID string) string { return topicBase + channelID }

// TriggerFunc queues one YouTube sync. accepted is false when the
// single-flight queue is busy; the notification then stays pending.
type TriggerFunc func(context.Context) (accepted bool, err error)

// retirement is a previous callback whose subscription is withdrawn.
type retirement struct {
	callback, secret string
	attempts         int
	nextAt           time.Time
}

// Service owns the subscription lease, the callback handler and the
// debounced sync trigger. Runtime state is in memory: after a restart the
// subscription is renewed at once and polling covers any missed upload.
type Service struct {
	channelID string
	topic     string
	hub       string
	client    *http.Client
	trigger   TriggerFunc
	now       func() time.Time
	log       io.Writer

	mu       sync.Mutex
	enabled  bool
	callback string
	secret   string
	// generation discards results of a hub request sent under an older
	// configuration.
	generation uint64
	// renewAt is when the next subscribe request is due.
	renewAt time.Time
	// requestedAt marks an outstanding subscribe request awaiting verification.
	requestedAt    time.Time
	verifiedAt     time.Time
	leaseExpiresAt time.Time
	lastError      string
	retire         *retirement
	// unsubscribedAt marks an outstanding unsubscribe awaiting verification.
	unsubscribedAt time.Time
	// pending is set by a verified notification until a sync is accepted.
	pending          bool
	notifiedAt       time.Time
	lastTriggeredAt  time.Time
	nextTriggerTryAt time.Time

	cancel context.CancelFunc
	wg     sync.WaitGroup
}

// New builds a disabled service for channelID; Configure enables it. client
// may be nil; its timeout and redirect policy are replaced with fixed bounds.
func New(channelID string, client *http.Client, trigger TriggerFunc) *Service {
	if client == nil {
		client = &http.Client{}
	}
	copy := *client
	copy.Timeout = 10 * time.Second
	copy.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	return &Service{
		channelID: channelID,
		topic:     Topic(channelID),
		hub:       HubURL,
		client:    &copy,
		trigger:   trigger,
		now:       time.Now,
		log:       os.Stderr,
	}
}

// Configure applies the operator settings. Enabling requires a valid callback
// and secret. A change subscribes at the next step; disabling or moving the
// callback also withdraws the previous subscription.
func (s *Service) Configure(enabled bool, callback, secret string) error {
	if enabled {
		if err := (Options{CallbackURL: callback, Secret: secret, ChannelID: s.channelID}).Validate(); err != nil {
			return err
		}
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if enabled == s.enabled && callback == s.callback && secret == s.secret {
		return nil
	}
	if s.enabled && (!enabled || callback != s.callback) {
		s.retire = &retirement{callback: s.callback, secret: s.secret}
	}
	if enabled && s.retire != nil && s.retire.callback == callback {
		s.retire = nil
	}
	s.enabled, s.callback, s.secret = enabled, callback, secret
	s.generation++
	s.renewAt = time.Time{}
	s.requestedAt, s.verifiedAt, s.leaseExpiresAt = time.Time{}, time.Time{}, time.Time{}
	s.lastError = ""
	if !enabled {
		s.pending = false
	}
	return nil
}

// settings returns the active configuration for the admin module.
func (s *Service) settings() (enabled bool, callback, secret string) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.enabled, s.callback, s.secret
}

// Start runs the renewal and trigger loop.
func (s *Service) Start() {
	s.mu.Lock()
	if s.cancel != nil {
		s.mu.Unlock()
		return
	}
	ctx, cancel := context.WithCancel(context.Background())
	s.cancel = cancel
	s.mu.Unlock()
	s.wg.Add(1)
	go func() {
		defer s.wg.Done()
		ticker := time.NewTicker(tickInterval)
		defer ticker.Stop()
		for {
			s.Step(ctx)
			select {
			case <-ctx.Done():
				return
			case <-ticker.C:
			}
		}
	}()
}

// Stop ends the loop. The hub lease is left to expire on its own.
func (s *Service) Stop() {
	s.mu.Lock()
	cancel := s.cancel
	s.cancel = nil
	s.mu.Unlock()
	if cancel != nil {
		cancel()
		s.wg.Wait()
	}
}

// Step performs at most one due unsubscribe, one due subscribe request and
// one due trigger.
func (s *Service) Step(ctx context.Context) {
	now := s.now()
	s.mu.Lock()
	var retire *retirement
	if s.retire != nil && !now.Before(s.retire.nextAt) {
		retire = s.retire
		retire.attempts++
		retire.nextAt = now.Add(subscribeRetry)
		// Recorded before sending: the hub may verify before it responds.
		s.unsubscribedAt = now
	}
	renew := false
	if s.enabled {
		if !s.requestedAt.IsZero() && !within(s.requestedAt, now) {
			// The hub never confirmed: the callback is probably unreachable.
			s.requestedAt = time.Time{}
			s.lastError = "websub_verification_missing"
			s.renewAt = now
			s.logf("youtube websub subscription was not verified: %s", s.lastError)
		}
		if renew = !now.Before(s.renewAt); renew {
			// Claim the slot so an overlapping Step cannot send a second request,
			// and accept a verification that arrives before the hub responds.
			s.renewAt = now.Add(subscribeRetry)
			s.requestedAt = now
		}
	}
	generation, callback, secret := s.generation, s.callback, s.secret
	fire := s.enabled && s.pending && !now.Before(s.notifiedAt.Add(debounce)) &&
		!now.Before(s.lastTriggeredAt.Add(minTriggerGap)) && !now.Before(s.nextTriggerTryAt)
	if fire {
		s.nextTriggerTryAt = now.Add(triggerRetry)
	}
	s.mu.Unlock()

	if retire != nil {
		s.withdraw(ctx, retire, now)
	}
	if renew {
		s.renew(ctx, generation, callback, secret, now)
	}
	if fire && s.trigger != nil {
		accepted, err := s.trigger(ctx)
		s.mu.Lock()
		if err == nil && accepted {
			s.pending = false
			s.lastTriggeredAt = s.now()
		}
		s.mu.Unlock()
		if err != nil {
			s.logf("youtube websub sync not queued: %s", "trigger_failed")
		}
	}
}

func (s *Service) withdraw(ctx context.Context, retire *retirement, now time.Time) {
	err := s.request(ctx, "unsubscribe", retire.callback, retire.secret)
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.retire != retire {
		return
	}
	if err == nil {
		s.retire = nil
		return
	}
	s.unsubscribedAt = time.Time{}
	s.logf("youtube websub unsubscribe failed: %s", err.Error())
	if retire.attempts >= unsubscribeAttempts {
		s.retire = nil
	}
}

func (s *Service) renew(ctx context.Context, generation uint64, callback, secret string, now time.Time) {
	err := s.request(ctx, "subscribe", callback, secret)
	s.mu.Lock()
	defer s.mu.Unlock()
	if generation != s.generation {
		return
	}
	if err != nil {
		s.requestedAt = time.Time{}
		s.lastError = err.Error()
		s.renewAt = now.Add(subscribeRetry)
		s.logf("youtube websub subscribe failed: %s", err.Error())
		return
	}
	// lastError stays until the hub verifies this request. A verification
	// that already arrived has set the renewal from the granted lease.
	if s.requestedAt.Equal(now) {
		s.renewAt = now.Add(time.Duration(LeaseSeconds) * time.Second / 2)
	}
}

// hubError is a fixed code; upstream bodies never leave this package.
type hubError struct{ code string }

func (e *hubError) Error() string { return e.code }

func (s *Service) request(ctx context.Context, mode, callback, secret string) error {
	form := url.Values{
		"hub.mode":     {mode},
		"hub.topic":    {s.topic},
		"hub.callback": {callback},
		"hub.verify":   {"async"},
	}
	if mode == "subscribe" {
		form.Set("hub.secret", secret)
		form.Set("hub.lease_seconds", strconv.Itoa(LeaseSeconds))
	}
	req, err := http.NewRequestWithContext(ctx, http.MethodPost, s.hub, strings.NewReader(form.Encode()))
	if err != nil {
		return &hubError{"websub_invalid_request"}
	}
	req.Header.Set("Content-Type", "application/x-www-form-urlencoded")
	req.Header.Set("User-Agent", "kano-navi-go/websub")
	resp, err := s.client.Do(req)
	if err != nil {
		if errors.Is(err, context.DeadlineExceeded) {
			return &hubError{"websub_hub_timeout"}
		}
		return &hubError{"websub_hub_unavailable"}
	}
	defer resp.Body.Close()
	_, _ = io.Copy(io.Discard, io.LimitReader(resp.Body, maxHubResponseBytes))
	switch {
	case resp.StatusCode == http.StatusAccepted || resp.StatusCode == http.StatusNoContent:
		return nil
	case resp.StatusCode >= 300 && resp.StatusCode < 400:
		return &hubError{"websub_hub_redirect_rejected"}
	case resp.StatusCode == http.StatusTooManyRequests:
		return &hubError{"websub_hub_rate_limited"}
	default:
		return &hubError{"websub_hub_http_error"}
	}
}

// ServeHTTP answers hub verification (GET) and content notifications (POST).
// While disabled the route looks absent, except to verify a withdrawal.
func (s *Service) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	s.mu.Lock()
	open := s.enabled || within(s.unsubscribedAt, s.now())
	s.mu.Unlock()
	if !open {
		w.Header().Set("Content-Type", "application/json; charset=utf-8")
		w.WriteHeader(http.StatusNotFound)
		_, _ = io.WriteString(w, `{"error":"api_not_found"}`)
		return
	}
	switch r.Method {
	case http.MethodGet:
		s.verify(w, r)
	case http.MethodPost:
		s.notify(w, r)
	default:
		w.Header().Set("Allow", "GET, POST")
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
	}
}

// verify echoes the challenge only for this channel's topic and only for a
// request this process wants: a subscription while enabled, or the
// withdrawal it just sent.
func (s *Service) verify(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query()
	if query.Get("hub.topic") != s.topic {
		http.NotFound(w, r)
		return
	}
	challenge := query.Get("hub.challenge")
	now := s.now()
	s.mu.Lock()
	defer s.mu.Unlock()
	switch query.Get("hub.mode") {
	case "subscribe":
		if !s.enabled {
			http.NotFound(w, r)
			return
		}
		if challenge == "" || len(challenge) > maxChallengeBytes {
			http.Error(w, "bad request", http.StatusBadRequest)
			return
		}
		lease, err := strconv.Atoi(query.Get("hub.lease_seconds"))
		if err != nil || lease <= 0 || lease > LeaseSeconds*4 {
			lease = LeaseSeconds
		}
		if within(s.requestedAt, now) {
			granted := time.Duration(lease) * time.Second
			s.verifiedAt = now
			s.leaseExpiresAt = now.Add(granted)
			s.requestedAt = time.Time{}
			s.renewAt = now.Add(max(granted/2, minRenewal))
			s.lastError = ""
			s.logf("youtube websub subscription verified")
		}
		writeChallenge(w, challenge)
	case "unsubscribe":
		if !within(s.unsubscribedAt, now) || challenge == "" || len(challenge) > maxChallengeBytes {
			http.NotFound(w, r)
			return
		}
		s.unsubscribedAt = time.Time{}
		writeChallenge(w, challenge)
	case "denied":
		if s.enabled && within(s.requestedAt, now) {
			s.requestedAt = time.Time{}
			s.lastError = "websub_hub_denied"
			s.renewAt = now.Add(subscribeRetry)
		}
		w.WriteHeader(http.StatusOK)
	default:
		http.NotFound(w, r)
	}
}

func writeChallenge(w http.ResponseWriter, challenge string) {
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.Header().Set("Cache-Control", "no-store")
	_, _ = io.WriteString(w, challenge)
}

// within reports whether a hub request sent at t still awaits its verdict.
func within(t, now time.Time) bool {
	return !t.IsZero() && now.Sub(t) <= verifyWindow
}

// notify accepts a signed Atom notification. Invalid signatures and foreign
// entries are acknowledged without effect, as WebSub requires, so a sender
// cannot probe the secret.
func (s *Service) notify(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(io.LimitReader(r.Body, MaxNotificationBytes+1))
	if err != nil {
		http.Error(w, "bad request", http.StatusBadRequest)
		return
	}
	if len(body) > MaxNotificationBytes {
		http.Error(w, "request too large", http.StatusRequestEntityTooLarge)
		return
	}
	s.mu.Lock()
	enabled, secret := s.enabled, s.secret
	s.mu.Unlock()
	if enabled && validSignature(r.Header.Get("X-Hub-Signature"), secret, body) && containsChannelVideo(body, s.channelID) {
		s.mu.Lock()
		if s.enabled && s.secret == secret {
			s.pending = true
			s.notifiedAt = s.now()
		}
		s.mu.Unlock()
	}
	w.WriteHeader(http.StatusAccepted)
}

func validSignature(header, secret string, body []byte) bool {
	algorithm, digest, ok := strings.Cut(strings.TrimSpace(header), "=")
	if !ok || secret == "" {
		return false
	}
	var factory func() hash.Hash
	switch strings.ToLower(algorithm) {
	case "sha1":
		factory = sha1.New
	case "sha256":
		factory = sha256.New
	case "sha384":
		factory = sha512.New384
	case "sha512":
		factory = sha512.New
	default:
		return false
	}
	expected, err := hex.DecodeString(digest)
	if err != nil {
		return false
	}
	mac := hmac.New(factory, []byte(secret))
	mac.Write(body)
	return hmac.Equal(mac.Sum(nil), expected)
}

// atomFeed matches local names only, like the RSS parser: the hub sends the
// Atom feed with the yt: extension elements.
type atomFeed struct {
	Entries []struct {
		VideoID   string `xml:"videoId"`
		ChannelID string `xml:"channelId"`
	} `xml:"entry"`
}

// containsChannelVideo reports whether the feed names a video of channel.
// Deleted-entry notices carry no entry and do not trigger a sync.
func containsChannelVideo(body []byte, channel string) bool {
	var feed atomFeed
	decoder := xml.NewDecoder(bytes.NewReader(body))
	decoder.Strict = true
	if decoder.Decode(&feed) != nil {
		return false
	}
	for _, entry := range feed.Entries {
		if strings.TrimSpace(entry.ChannelID) == channel && videoPattern.MatchString(strings.TrimSpace(entry.VideoID)) {
			return true
		}
	}
	return false
}

// Status is the operator projection. It carries whether a secret exists,
// never the secret.
func (s *Service) Status() map[string]any {
	s.mu.Lock()
	defer s.mu.Unlock()
	timestamp := func(t time.Time) any {
		if t.IsZero() {
			return nil
		}
		return t.UTC().Format(time.RFC3339)
	}
	optional := func(value string) any {
		if value == "" {
			return nil
		}
		return value
	}
	var renewal any
	if s.enabled {
		renewal = timestamp(s.renewAt)
	}
	return map[string]any{
		"enabled":            s.enabled,
		"callbackUrl":        optional(s.callback),
		"callbackPath":       CallbackPath,
		"secretConfigured":   s.secret != "",
		"verified":           s.enabled && !s.leaseExpiresAt.IsZero() && s.now().Before(s.leaseExpiresAt),
		"leaseExpiresAt":     timestamp(s.leaseExpiresAt),
		"nextRenewalAt":      renewal,
		"pending":            s.pending,
		"lastNotificationAt": timestamp(s.notifiedAt),
		"lastTriggeredAt":    timestamp(s.lastTriggeredAt),
		"lastError":          optional(s.lastError),
	}
}

func (s *Service) logf(format string, args ...any) {
	if s.log != nil {
		fmt.Fprintf(s.log, "kano-go: "+format+"\n", args...)
	}
}
